import {artifactIconStyle} from './campaign-artifact-art.mjs';
import growthMeta from '../assets/pets/growth-meta-v2.json' with {type:'json'};
import {artifactLevel,artifactUpgradeCost,upgradeArtifact,mirrorRules,ARTIFACTS,equippedArtifact,equipArtifact,artifactBonuses,swordRules} from './campaign-artifacts.mjs';
import {selectCompanion,COMPANION_STATS,deployCompanion} from './campaign-companion.mjs';
import {PETS,PET_IDS,mirrorUnlocked,petRecord,petExperience,petStats,PET_SKILLS,evolvePet} from './campaign-pet-data.mjs';
export function petArtStyle(m,index){const r=m.frames[index].rect,[w,h]=m.size;return `background-image:url('assets/pets/${m.file}');background-size:${w/r[2]*100}% ${h/r[3]*100}%;background-position:${r[0]/Math.max(1,w-r[2])*100}% ${r[1]/Math.max(1,h-r[3])*100}%;aspect-ratio:${r[2]}/${r[3]}`;}
export const petIcon=(id,form=0)=>petPortraitStyle(id,form);
export function petPortraitStyle(id,form=0){const m=growthMeta.portraits,f=m.frames.find(f=>f.pet===id&&f.form===Math.max(0,Math.min(2,form))),r=f.rect,side=Math.min(m.size[0],m.size[1],Math.max(r[2],r[3])*1.06),x=Math.max(0,Math.min(m.size[0]-side,r[0]+r[2]/2-side/2)),y=Math.max(0,Math.min(m.size[1]-side,r[1]+r[3]/2-side/2));return `background-image:url('assets/pets/${m.file}');background-size:${m.size[0]/side*100}% ${m.size[1]/side*100}%;background-position:${x/Math.max(1,m.size[0]-side)*100}% ${y/Math.max(1,m.size[1]-side)*100}%;aspect-ratio:1`;}
export const petSkillStyle=(id,index)=>petArtStyle(growthMeta.icons,PETS[id].row*3+index);
export function artifactPanel(p,ui={}){
 const id=ui.artifactSelected||equippedArtifact(p)||'mirror',definition=ARTIFACTS[id],level=artifactLevel(p,id),open=level>0,cost=artifactUpgradeCost(p,id),equipped=equippedArtifact(p)===id,mirror=id==='mirror',rules=mirror?mirrorRules(p):swordRules(p),health=20+Math.max(0,level-1)*5,attack=3+Math.max(0,level-1),source=mirror?4:6;
 return `<div class="artifact-choices">${Object.entries(ARTIFACTS).map(([key,d])=>`<button data-artifact-select="${key}" class="${id===key?'selected':''}"><i class="artifact-art ${key}" style="${artifactIconStyle(key)}"></i><span><b>${d.name}</b><small>${artifactLevel(p,key)?'Lv.'+artifactLevel(p,key):'第'+(key==='mirror'?4:6)+'关首领掉落'}${equippedArtifact(p)===key?' · 已装备':''}</small></span></button>`).join('')}</div><div class="mirror-layout"><section class="mirror-display"><i class="artifact-large artifact-art ${id}" style="${artifactIconStyle(id)}"></i><small>${mirror?'THE BEASTBINDING MIRROR':'THE CELESTIAL SWORD'}</small><h3>${definition.name} ${open?'Lv.'+level:''}</h3><p>${mirror?'凝镜聚灵 · 生命与捕捉':'御剑成阵 · 攻击与剑雨'}</p></section><section class="mirror-description"><h3>${open?equipped?'当前装备中':'已拥有 · 尚未装备':'尚未获得'}</h3><p>第${source}关首领被击败后掉落，靠近按C拾取。一个法器槽，一次装备一件；属性只在装备时生效。</p>${mirror?`<p>装备后基础生命+${health}。宠物副本中降低目标生命，在${rules.range}距离内按 <kbd>V</kbd>，维持${rules.channel}秒镜光捕捉。</p><dl><dt>装备生命加成</dt><dd>+${health}</dd><dt>满血捕捉率</dt><dd>${Math.round((.12+rules.chanceBonus)*100)}%</dd><dt>低血上限</dt><dd>${Math.round(Math.min(.95,.9+rules.chanceBonus)*100)}%</dd><dt>再次使用</dt><dd>${rules.cooldown.toFixed(2)}秒</dd></dl>`:`<p>装备后基础攻击+${attack}。按住 <kbd>Q</kbd>，鼠标下方出现剑阵，天剑持续坠落；移动鼠标可引导落点，松开停止。</p><dl><dt>装备攻击加成</dt><dd>+${attack}</dd><dt>单剑伤害</dt><dd>${rules.damage}</dd><dt>持续 / 冷却</dt><dd>${rules.duration} / ${rules.cooldown}秒</dd><dt>法力消耗</dt><dd>启动${rules.startMana} · 每秒${rules.manaPerSecond}</dd></dl>`}<button data-artifact-equip="${id}" ${open?'':'disabled'}>${equipped?'卸下'+definition.name:'装备'+definition.name}</button><div class="artifact-upgrade"><strong>${open?'法宝等级 '+level+' / '+definition.maxLevel:'拾取后开放金币升级'}</strong><button data-artifact-upgrade="${id}" ${cost===null?'disabled':''}>${cost===null?open?'已满级':'尚未获得':'升级法宝 · '+cost+'金币'}</button><small>${mirror?'每级：生命+5、捕捉率+1个百分点、范围+10、冷却−0.15秒。':'每级：装备攻击+1、单剑伤害+3。'}金币不足不扣费；重复拾取不重置等级。</small></div></section></div>`;
}
export function petPanel(ui,p){const pets=petRecord(p),selected=pets.find(v=>v.id===ui.petSelected)||pets.find(v=>v.id===p.activePetId)||pets[0],d=selected&&PETS[selected.kind],stats=selected&&petStats(selected),xp=selected&&petExperience(selected.exp||0),vitals=selected&&(ui.getWorld()?.campaign.companionStates?.[selected.id]||selected.vitals),nextForm=selected?(selected.form||0)+1:0,canEvolve=selected&&selected.form<2&&xp.level>=(selected.form===0?5:10);return `<div class="pet-archive"><section><div class="section-title"><h3>灵宠背包</h3><small>已收伏 ${pets.length} 只 · 最多一只出战</small></div><div class="pet-bag-grid">${pets.map(v=>`<button class="pet-owned ${v.id===selected?.id?'selected':''}" data-pet-select="${v.id}" aria-label="查看${PETS[v.kind].name}"><i style="${petIcon(v.kind,v.form)}"></i>${p.activePetId===v.id?'<em class="pet-active-badge">出战中</em>':''}<strong>${PETS[v.kind].name}</strong><small>Lv.${petExperience(v.exp||0).level} · 形态 ${v.form+1} · ${PETS[v.kind].forms[v.form]}</small></button>`).join('')||'<div class="pet-empty"><h3>尚未收伏灵宠</h3><p>通关第5、7、9关后，在关卡详情进入宠物副本。击败首领后，新的灵兽会出现。</p><p>装备收妖镜，降低灵宠生命后按 V 捕捉。</p></div>'}</div><div class="pet-places">${PET_IDS.map(id=>`<div><i style="${petIcon(id)}"></i><span>第${PETS[id].stage}关 · ${PETS[id].name}<small>通关本关后解锁专属副本</small></span></div>`).join('')}</div></section><aside class="pet-description">${d?`<i class="pet-portrait" style="${petIcon(d.id,selected.form)}"></i><h3>${d.name}</h3><button class="pet-deploy-button" data-pet-deploy="${selected.id}" >${p.activePetId===selected.id?'取消出战':'设为出战灵宠'}</button><p class="pet-deploy-note">${ui.getWorld()?'回收再出战保持本关生命、法力；一次只可上场一只。':p.activePetId===selected.id?'下一次进入关卡时，它会自动出现在身边。':'选择一只已捕获灵宠，陪同下一次关卡。'}</p><p>${d.description}</p><dl><dt>等级 / 经验</dt><dd>Lv.${xp.level} · ${xp.xp}/${xp.next}</dd><dt>生命</dt><dd>${Math.ceil(vitals?.hp??stats.maxHp)} / ${stats.maxHp}</dd><dt>法力</dt><dd>${Math.floor(vitals?.mp??stats.maxMp)} / ${stats.maxMp}</dd><dt>攻击力</dt><dd>${stats.damage}</dd><dt>捕获个体差异</dt><dd>生命${Math.round(((selected.traits?.hp??1)-1)*100)}% / 法力${Math.round(((selected.traits?.mp??1)-1)*100)}% / 攻击${Math.round(((selected.traits?.attack??1)-1)*100)}%</dd><dt>当前形态</dt><dd>${d.forms[selected.form]}</dd><dt>捕捉地点</dt><dd>第${selected.capturedStage}关 · 宠物副本</dd><dt>伴战方式</dt><dd>${COMPANION_STATS[d.id].ranged?'灵弹支援':'近身扑爪'}</dd></dl><div class="pet-skill-cards">${PET_SKILLS[d.id].map((skill,i)=>`<article class="has-tip ${i>selected.form?'locked':''}" data-tip="${skill.name}：${skill.text} 消耗${skill.cost}法力，冷却${skill.cd}秒。"><i style="${petSkillStyle(d.id,i)}"></i><div><strong>${skill.name}</strong><small>${i>selected.form?'形态'+(i+1)+'解锁':skill.cost+'法力 · '+skill.cd+'秒'}</small><p>${skill.text}</p></div></article>`).join('')}</div><button class="pet-evolve-button" data-pet-evolve="${selected.id}" ${!canEvolve||ui.getWorld()?'disabled':''}>${selected.form>=2?'已达最终形态':canEvolve?'进化为 · '+d.forms[nextForm]:'灵宠'+(selected.form===0?5:10)+'级可进化'}</button><p class="pet-deploy-note">出战时小怪每只5宠物经验、首领25；5级和10级在出战整备页手动进化，各多解锁一招。</p><div class="pet-form-line">${d.forms.map((n,i)=>`<span class="${i===selected.form?'active':''}"><b>0${i+1}</b>${n}</span>`).join('')}</div><p class="system-note">出战后自动跟随、跳上台面并协助攻击；同一次关卡内回收、换宠再放出保留生命和法力；重新进入关卡恢复满血满蓝。捕捉阶段自动停手。技能自动施放并消耗独立法力，法力不足时使用普通攻击。</p>`:'<i class="mirror-icon"></i><h3>循灵而行</h3><p>选择已捕获的灵宠，查看它的来历与形态。</p>'}</aside></div>`;}
export function handlePetUI(ui,b){if(b.dataset.artifactSelect){ui.artifactSelected=b.dataset.artifactSelect;ui.render();return true;}if(b.dataset.artifactEquip){ui.mutate(()=>{const p=ui.getProfile(),id=equippedArtifact(p)===b.dataset.artifactEquip?null:b.dataset.artifactEquip,w=ui.getWorld();if(w)w.campaign.noStatHealOnce=true;return equipArtifact(p,id);});return true;}if(b.dataset.artifactUpgrade){ui.mutate(()=>upgradeArtifact(ui.getProfile(),b.dataset.artifactUpgrade));return true;}if(b.dataset.petEvolve){ui.mutate(()=>{if(ui.getWorld())throw Error('请在世界地图进化灵宠');return evolvePet(ui.getProfile(),b.dataset.petEvolve);});return true;}if(b.dataset.petDeploy){ui.mutate(()=>{const p=ui.getProfile(),id=p.activePetId===b.dataset.petDeploy?null:b.dataset.petDeploy;return ui.getWorld()?deployCompanion(ui.getWorld(),id):selectCompanion(p,id);});return true;}if(b.dataset.petSelect){ui.petSelected=b.dataset.petSelect;ui.render();return true;}if(b.hasAttribute('data-mirror-equip')){ui.mutate(()=>{const p=ui.getProfile();if(!mirrorUnlocked(p))throw Error('击败第4关首领后按C拾取收妖镜');const w=ui.getWorld();if(w)w.campaign.noStatHealOnce=true;return equipArtifact(p,equippedArtifact(p)==='mirror'?null:'mirror');});return true;}return false;}
